# 1. 헥스 문자열 정리 (포맷팅 및 공백 제거)
clean_hex = hex_data.replace(" ", "").replace("\n", "")
print(f"[DEBUG 1] 정리된 헥스 데이터 길이: {len(clean_hex)} bytes")

# 2. 바이트로 변환
try:
    byte_data = binascii.unhexlify(clean_hex)
    print(f"[DEBUG 2] 바이트 변환 완료. 총 길이: {len(byte_data)} bytes")
except Exception as e:
    print(f"[ERROR] 바이트 변환 실패: {e}")
    exit()

# 3. 페이크 플래그 확인
print(f"[DEBUG 3] 시작 부분 디코딩: {byte_data[:15].decode('ascii', errors='ignore')}")

# 4. 파일로 저장 (stegsnow 도구 적용용)
filename = "snow_payload.txt"
with open(filename, "wb") as f:
    f.write(byte_data)
print(f"[DEBUG 4] 바이너리 데이터를 '{filename}'로 성공적으로 저장했습니다.")

# 5. [추가 확인] 단순 이진 치환 방식인지 디버깅 시도
print("\n[DEBUG 5-1] 단순 이진 디코딩 시도 (Space=0, Tab=1)")
binary_str = ""
for b in byte_data[13:]:  # 페이크 플래그 부분 제외
    if b == 0x20:
        binary_str += "0"
    elif b == 0x09:
        binary_str += "1"
    # 0x0A (개행)은 무시

print(f"[*] 추출된 이진 문자열 길이: {len(binary_str)}")
print(f"[*] 처음 64비트: {binary_str[:64]}")

ascii_result_1 = ""
for i in range(0, len(binary_str), 8):
    chunk = binary_str[i:i+8]
    if len(chunk) == 8:
        ascii_result_1 += chr(int(chunk, 2))
print(f"[*] 변환 결과: {ascii_result_1[:50]} ... (의미 없는 문자열이면 stegsnow 전용입니다.)")

print("\n[DEBUG 5-2] 단순 이진 디코딩 시도 (Space=1, Tab=0)")
binary_str_rev = binary_str.replace('0','X').replace('1','0').replace('X','1')
ascii_result_2 = ""
for i in range(0, len(binary_str_rev), 8):
    chunk = binary_str_rev[i:i+8]
    if len(chunk) == 8:
        ascii_result_2 += chr(int(chunk, 2))
print(f"[*] 변환 결과: {ascii_result_2[:50]} ...")